+
+test("consume uses the batch that expires first (FEFO)", () => {
+  const store = fresh();
+  // Milk: HD-1026 (id 3) expires 2026-11-02, HD-1022 (id 4) expires 2026-10-29.
+  const used = consume(store, 2, 3, { at, ref: "bechamel" });
+  assert.deepEqual(used, [
+    { batchId: 4, qty: 2 },
+    { batchId: 3, qty: 1 },
+  ]);
+});
+
+test("batches without expiry are used last; ties go to the earlier receipt, then lower id", () => {
+  const store = fresh();
+  const base = { itemId: 2, location: "fridge" };
+  store.data.batches.push(
+    { ...base, id: 900, lot: "NOEXP", qty: 5, receivedOn: "2026-10-01", expires: null },
+    { ...base, id: 902, lot: "TIE-B", qty: 1, receivedOn: "2026-10-20", expires: "2026-10-29" },
+    { ...base, id: 901, lot: "TIE-A", qty: 1, receivedOn: "2026-10-20", expires: "2026-10-29" },
+  );
+  const used = consume(store, 2, 13, { at });
+  assert.deepEqual(used.map((u) => u.batchId), [901, 902, 4, 3, 900]);
+});
